package com.lianxibu.site.domain.jobs;
import static org.junit.jupiter.api.Assertions.*;import java.time.*;import org.junit.jupiter.api.Test;
class CollectorMemoryFactsTest {
 Instant at=Instant.parse("2026-01-01T00:10:00Z");String epoch="00000000-0000-4000-8000-000000000001";
 CollectorMemoryFacts.Snapshot snapshot(Long maximum){return new CollectorMemoryFacts.Snapshot(epoch,"a".repeat(64),at.minusSeconds(60),1,12,at,256L<<20,"b".repeat(64),maximum,0,2);}
 @Test void completeNativeFrameKeepsAllIdentityRawCountersAndControlledBudgetWithoutHealthyBoolean(){var raw=snapshot(192L<<20);var value=new CollectorMemoryFacts.Evidence("fictional-node",1,true,192L<<20,1,raw,at,at.plusSeconds(1));assertEquals(256L<<20,value.snapshot().rssBytes());assertEquals(2,value.snapshot().oomKills());assertEquals("CollectorMemoryFacts[redacted]",value.toString());assertEquals("CollectorMemorySnapshot[redacted]",raw.toString());}
 @Test void actualMissingHistoryAndNativeUnlimitedRemainDistinctUnknownInputs(){var missing=new CollectorMemoryFacts.Evidence("fictional-node",1,true,192L<<20,0,null,null,at);assertNull(missing.snapshot());var unlimited=new CollectorMemoryFacts.Evidence("fictional-node",1,true,192L<<20,1,snapshot(null),at,at);assertNull(unlimited.snapshot().maximumBytes());assertThrows(RuntimeException.class,()->new CollectorMemoryFacts.Evidence("fictional-node",1,true,192L<<20,1,null,null,at));assertThrows(RuntimeException.class,()->new CollectorMemoryFacts.Evidence("fictional-node",1,true,192L<<20,0,snapshot(null),at,at));}
 @Test void malformedIdentityUnsafeCountersIncompletePrecisionAndFutureTimesFailClosed(){for(String node:new String[]{"","bad\nnode","x".repeat(65),"\ud800"})assertThrows(RuntimeException.class,()->new CollectorMemoryFacts.Evidence(node,1,true,192L<<20,0,null,null,at));assertThrows(RuntimeException.class,()->new CollectorMemoryFacts.Evidence("fictional-node",9007199254740992L,true,192L<<20,0,null,null,at));assertThrows(RuntimeException.class,()->new CollectorMemoryFacts.Evidence("fictional-node",1,true,0,0,null,null,at));assertThrows(RuntimeException.class,()->new CollectorMemoryFacts.Evidence("fictional-node",1,true,192L<<20,1,snapshot(null),at.minusSeconds(1),at));assertThrows(RuntimeException.class,()->new CollectorMemoryFacts.Evidence("fictional-node",1,true,192L<<20,1,snapshot(null),at,at.minusSeconds(1)));assertThrows(RuntimeException.class,()->new CollectorMemoryFacts.Snapshot(epoch,"a".repeat(64),at.plusSeconds(1),1,12,at,1,"b".repeat(64),null,0,0));assertThrows(RuntimeException.class,()->new CollectorMemoryFacts.Snapshot(epoch,"bad",at,1,12,at,1,"b".repeat(64),null,0,0));assertThrows(RuntimeException.class,()->new CollectorMemoryFacts.Snapshot(epoch,"a".repeat(64),at,1,0,at,1,"b".repeat(64),null,0,0));assertThrows(RuntimeException.class,()->new CollectorMemoryFacts.Snapshot(epoch,"a".repeat(64),at,1,12,at.plusNanos(1),1,"b".repeat(64),null,0,0));}
}
